-- Virtual Table Definitions --


-- Access lnav's environment variables through this table.
CREATE TABLE lnav_db.environ (
    name TEXT PRIMARY KEY,
    value TEXT
);

-- Access app files in the lnav configuration directories
CREATE TABLE lnav_db.lnav_app_files (
    name TEXT PRIMARY KEY,
    app TEXT,
    filepath TEXT,
    content BLOB HIDDEN
);

CREATE TABLE lnav_db.lnav_apps (
    name TEXT PRIMARY KEY,
    description TEXT,
    root TEXT
);

CREATE TABLE lnav_db.all_thread_ids (
    thread_id TEXT PRIMARY KEY,  -- The thread ID
    earliest DATETIME,           -- The earliest time this ID was seen
    latest DATETIME,             -- The latest time this ID was seen
    duration INTEGER,            -- The amount of time between earliest and latest in microseconds
    errors INTEGER,              -- The number of error messages associated with this ID
    warnings INTEGER,            -- The number of warning messages associated with this ID
    total INTEGER                -- The total number of messages associated with this ID
);

-- Access statistics for filters through this table.
CREATE TABLE lnav_db.lnav_view_filter_stats (
    view_name TEXT,     -- The name of the view.
    filter_id INTEGER,  -- The filter identifier.
    hits      INTEGER   -- The number of lines that matched this filter.
);

-- Access lnav's log breakpoints through this table.
CREATE TABLE lnav_db.lnav_log_breakpoints (
    schema_id TEXT NOT NULL,                    -- The schema identifier for the breakpoint.  Matches the log_msg_schema in the all_logs table.
    description TEXT NOT NULL,                  -- A human-readable description of the breakpoint (e.g. format:file:line).
    type TEXT NOT NULL DEFAULT 'src_location',  -- The source of the schema ID, either 'src_location' or 'message_schema'.
    enabled INTEGER NOT NULL DEFAULT 1          -- Indicates whether the breakpoint is active.
);

-- Access lnav's views through this table.
CREATE TABLE lnav_db.lnav_views (
    name TEXT PRIMARY KEY,  -- The name of the view.
    top INTEGER,            -- The number of the line at the top of the view, starting from zero.
    left INTEGER,           -- The left position of the viewport.
    height INTEGER,         -- The height of the viewport.
    inner_height INTEGER,   -- The number of lines in the view.
    top_time DATETIME,      -- The time of the top line in the view, if the content is time-based.
    top_file TEXT,          -- The file the top line is from.
    paused INTEGER,         -- Indicates if the view is paused and will not load new data.
    search TEXT,            -- The text to search for in the view.
    filtering INTEGER,      -- Indicates if the view is applying filters.
    movement TEXT,          -- The movement mode, either 'top' or 'cursor'.
    top_meta TEXT,          -- A JSON object that contains metadata related to the top line in the view.
    selection INTEGER,      -- The number of the line that is focused for selection.
    options TEXT,           -- A JSON object that contains optional settings for this view.
    selected_text TEXT,     -- A JSON object that contains information about the text selected by the mouse in the view.
    row_details TEXT        -- A JSON object that contains information about the focused row.
);

--
CREATE TABLE lnav_db.lnav_view_files (
    view_name TEXT,     -- The name of the view.
    filepath  TEXT,     -- The path to the file.
    visible   INTEGER   -- Indicates whether or not the file is shown.
);

-- Access lnav's view stack through this table.
CREATE TABLE lnav_db.lnav_view_stack (
    name TEXT
);

-- Access lnav's filters through this table.
CREATE TABLE lnav_db.lnav_view_filters (
    view_name TEXT,                    -- The name of the view.
    filter_id INTEGER DEFAULT 0,       -- The filter identifier.
    enabled   INTEGER DEFAULT 1,       -- Indicates if the filter is enabled/disabled.
    type      TEXT    DEFAULT 'out',   -- The type of filter (i.e. in/out).
    language  TEXT    DEFAULT 'regex', -- The filter language.
    pattern   TEXT                     -- The filter pattern.
);

CREATE TABLE lnav_db.all_opids (
    opid TEXT PRIMARY KEY,  -- The operation ID
    earliest DATETIME,      -- The earliest time this ID was seen
    latest DATETIME,        -- The latest time this ID was seen
    duration INTEGER,       -- The amount of time between earliest and latest in microseconds
    errors INTEGER,         -- The number of error messages associated with this ID
    warnings INTEGER,       -- The number of warning messages associated with this ID
    total INTEGER,          -- The total number of messages associated with this ID
    definition TEXT,        -- The name of the opid description from the log format, if available
    description TEXT        -- A description of the operation
);

-- Access lnav's open file list through this table.
