        if self.until_dt is not None:
            lines.append(f" |        = note: Maximum time cutoff is “{format_sql_time(self.until_dt)}”")
        return lines


def parse_args(argv: Sequence[str]) -> Options:
    opts = Options()
    args = list(argv[1:])
    idx = 0
    while idx < len(args):
        arg = args[idx]

        if arg == "--help":
            opts.help = True
        elif arg == "-h":
            opts.help = True
        elif arg == "-H":
            opts.internal_help = True
        elif arg == "-V":
            opts.version = True
        elif arg == "-u":
            opts.update_formats = True
        elif arg == "-r":
            opts.recursive = True
        elif arg == "-R":
            opts.load_rotated = True
        elif arg == "-n":
            opts.headless = True
        elif arg == "-N":
            opts.no_default = True
        elif arg == "-q":
            opts.quiet = True
        elif arg == "-t":
            opts.prepend_stdin_timestamps = True
        elif arg == "-C":
            opts.check_config = True
        elif arg == "-W":
            pass
        elif arg == "-m":
            opts.management_mode = True
        elif arg in ("-S", "--since"):
            idx += 1
            if idx >= len(args):
                raise ParseError(114, "invalid command-line arguments", "--since: 1 required TEXT missing")
            opts.since_text = args[idx]
        elif arg in ("-U", "--until"):
            idx += 1
            if idx >= len(args):
                raise ParseError(114, "invalid command-line arguments", "--until: 1 required TEXT missing")
            opts.until_text = args[idx]
        elif arg == "-d":
            idx += 1
            if idx >= len(args):
                raise ParseError(114, "invalid command-line arguments", "-d: 1 required FILE missing")
            opts.debug_file = args[idx]
        elif arg == "-I":
            idx += 1
            if idx >= len(args):
                raise ParseError(114, "invalid command-line arguments", "-I: 1 required TEXT:DIR missing")
            opts.extra_config_dirs.append(args[idx])
        elif arg == "-c":
            idx += 1
            if idx >= len(args):
                raise ParseError(114, "invalid command-line arguments", "-c: 1 required  missing")
            opts.command_options.append(args[idx])
        elif arg == "-f":
            idx += 1
            if idx >= len(args):
                raise ParseError(114, "invalid command-line arguments", "-f: 1 required  missing")
            opts.command_files.append(args[idx])
        elif arg == "-e":
            idx += 1
            if idx >= len(args):
                raise ParseError(114, "invalid command-line arguments", "-e: 1 required  missing")
            opts.shell_commands.append(args[idx])
        elif arg == "-i":
            idx += 1
            if idx >= len(args):
                raise ParseError(107, "invalid command-line arguments", "-i requires file")
            opts.install_arg = args[idx]
        elif arg.startswith("-"):
            remainder = " ".join(args[idx:])
            if " " in remainder:
                reason = f"The following arguments were not expected: {remainder}"
            else:
                reason = f"The following argument was not expected: {arg}"
            raise ParseError(109, "invalid command-line arguments", reason)
        else:
            opts.paths.append(arg)
        idx += 1

    if opts.management_mode and (opts.headless or opts.no_default):
        unexpected = []
        if opts.no_default:
            unexpected.append("-N")
        if opts.headless:
            unexpected.append("-n")
        raise ParseError(109, "invalid command-line arguments", f"The following arguments were not expected: {' '.join(unexpected)}")

    return opts


def parse_cutoff(value: str, name: str) -> datetime:
    parsed = parse_timestamp(value)
    if parsed is None:
        raise RuntimeCliError(1, [f"  error: invalid '{name}' time “{value}”", " reason: Unrecognized input"])
    return parsed


def execute_commands(runtime: RuntimeContext, state: State) -> None:
    commands: list[tuple[str, str, int]] = []

    for index, command in enumerate(runtime.opts.command_options, start=1):
        commands.append(("option", command, index))

    option_count = len(commands)
    for offset, command_file in enumerate(runtime.opts.command_files, start=1):
        commands.extend(read_script_command_file(command_file, option_count + offset))

    for source_kind, command, index in commands:
        if not command:
            continue
        prefix = command[0]
        if prefix not in ":;|":
            sys.stderr.write(INVALID_C_HELP.format(cmd=command))
            raise RuntimeCliError(105, [])

        if prefix == ":":
            run_builtin_command(state, command[1:].strip(), index)
        elif prefix == ";":
            execute_sql_command(state, command[1:], index)
        elif prefix == "|":
            execute_script(state, command[1:], index)


def read_script_command_file(path: str, index: int) -> list[tuple[str, str, int]]:
    if path == "-":
        text = sys.stdin.read()
    else:
        target = Path(path)
        if not target.exists():
            sys.stderr.write(
                f"  error: unknown script -- {path} -- file not found\n"
                f" --> command-option:{index}\n"
                f" | |{path:<35}\n"
            )
            return []
        text = target.read_text(encoding="utf-8")

    commands = []
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        commands.append(("script", stripped, index))
    return commands


def execute_script(state: State, script_ref: str, index: int) -> None:
    commands = read_script_command_file(script_ref, index)
    for _, command, inner_index in commands:
        prefix = command[0]
        if prefix == ":":
            run_builtin_command(state, command[1:].strip(), inner_index)
        elif prefix == ";":
            execute_sql_command(state, command[1:], inner_index)
        elif prefix == "|":
            execute_script(state, command[1:], inner_index)
        else:
            sys.stderr.write(INVALID_C_HELP.format(cmd=command))
            state.had_command_error = True


def run_builtin_command(state: State, command: str, index: int) -> None:
    parts = shlex.split(command)
    if not parts:
        return

    name = parts[0]
    args = parts[1:]

    if name == "filter-in":
        pattern = args[0] if args else ""
        state.visible_entries = [entry for entry in state.visible_entries if matches_filter(entry.raw_line, pattern)]
        for entry in state.visible_entries:
            entry.log_filters = "[1]"
        state.current_index = 0
        state.last_query = None
        return

    if name == "filter-out":
        pattern = args[0] if args else ""
        state.visible_entries = [entry for entry in state.visible_entries if not matches_filter(entry.raw_line, pattern)]
        state.current_index = 0
        state.last_query = None
        return

    if name == "goto":
        if not state.visible_entries or not args:
            return
        target = args[0]
        if re.fullmatch(r"-?\d+", target):
            index_value = max(0, min(int(target), len(state.visible_entries) - 1))
            state.current_index = index_value
            return
        target_time = parse_timestamp(target)
        if target_time is None:
            return
        for idx, entry in enumerate(state.visible_entries):
            if entry.log_time >= target_time:
                state.current_index = idx
                return
        state.current_index = len(state.visible_entries) - 1
        return

    if name in {
        "highlight",
        "highlight-field",
        "partition-name",
        "config",
        "save-session",
        "load-session",
    }:
        return

    if name == "write-csv-to":
        state.explicit_output = write_csv_output(state)
        return

    if name == "write-json-to":
        state.explicit_output = write_json_output(state)
        return

    if name == "write-jsonlines-to":
        state.explicit_output = write_jsonlines_output(state)
        return

    if name == "write-table-to":
        if state.last_query is not None:
            state.explicit_output = format_table(state.last_query)
        else:
            state.explicit_output = render_log_lines(state.visible_entries)
        return

    if name == "write-to":
        sys.stderr.write(WRITE_TO_HELP.format(index=index))
        state.had_command_error = True
        return

    sys.stderr.write(f"  error: unknown command: “{name}”\n")
    state.had_command_error = True


def execute_sql_command(state: State, sql: str, index: int) -> None:
    sql = sql.strip()
    special = normalize_sql(sql)
    if special == "select * from logline":
        state.last_query = query_logline_star(state)
        return

    db = sqlite3.connect(":memory:")
    db.row_factory = sqlite3.Row
    load_sqlite_schema(db, state)

    try:
        cursor = db.execute(sql)
        columns = [desc[0] for desc in cursor.description or []]
        rows = [tuple(row) for row in cursor.fetchall()] if columns else []
        state.last_query = QueryResult(columns=columns, rows=rows)
    except sqlite3.Error as exc:
        sys.stderr.write(
            f"  error: failed to compile SQL statement\n"
            f" reason: {exc}\n"
            f" --> command-option:{index}\n"
            f" | {sql:<35}\n"
        )
        state.had_command_error = True
    finally:
        db.close()


def load_sqlite_schema(db: sqlite3.Connection, state: State) -> None:
    db.execute(
        """
        CREATE TABLE all_logs (
            log_line INTEGER,
            log_time TEXT,
            log_level TEXT,
            log_msg_format TEXT,
            log_msg_values TEXT,
            log_msg_src TEXT,
            log_stack_trace TEXT,
            log_part TEXT,
            log_idle_msecs INTEGER,
            log_mark INTEGER,
            log_comment TEXT,
            log_tags TEXT,
            log_annotations TEXT,
            log_filters TEXT,
            log_text TEXT,
            log_body TEXT,
            log_path TEXT,
            log_actual_time TEXT,
            log_time_msecs INTEGER,
            ex_procname TEXT,
            ex_duration INTEGER
        )
        """
    )

    db.execute(
        """
        CREATE TABLE logline (
            log_line INTEGER,
            log_time TEXT,
            log_level TEXT,
            log_part TEXT,
            log_idle_msecs INTEGER,
            log_mark INTEGER,
            log_comment TEXT,
            log_tags TEXT,
            log_annotations TEXT,

Chunk ID: 82c6d0
Wall time: 0.0000 seconds
Process exited with code 0
Original token count: 2356
Output:
            log_annotations TEXT,
            log_filters TEXT,
            log_text TEXT,
            log_body TEXT
        )
        """
    )

    db.execute("CREATE TABLE environ (name TEXT, value TEXT)")

    for entry in state.visible_entries:
        epoch_msecs = int(entry.log_time.replace(tzinfo=timezone.utc).timestamp() * 1000)
        db.execute(
            """
            INSERT INTO all_logs VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                entry.log_line,
                format_sql_time(entry.log_time),
                entry.level,
                entry.body,
                "null",
                None,
                None,
                None,
                entry.log_idle_msecs,
                0,
                None,
                None,
                None,
                entry.log_filters,
                entry.raw_line,
                entry.body,
                entry.path,
                format_sql_time(entry.log_time),
                epoch_msecs,
                None,
                None,
            ),
        )

    if state.visible_entries:
        entry = state.visible_entries[min(state.current_index, len(state.visible_entries) - 1)]
        db.execute(
            """
            INSERT INTO logline VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                state.current_index,
                format_sql_time(entry.log_time),
                entry.level,
                None,
                0 if state.current_index == 0 else entry.log_idle_msecs,
                0,
                None,
                None,
                None,
                entry.log_filters,
                entry.raw_line,
                entry.body,
            ),
        )
    db.commit()


def query_logline_star(state: State) -> QueryResult:
    columns = [
        "log_line",
        "log_time",
        "log_level",
        "log_part",
        "log_idle_msecs",
        "log_mark",
        "log_comment",
        "log_tags",
        "log_annotations",
        "log_filters",
    ]
    if not state.visible_entries:
        return QueryResult(columns=columns, rows=[])
    entry = state.visible_entries[min(state.current_index, len(state.visible_entries) - 1)]
    row = (
        state.current_index,
        format_sql_time(entry.log_time),
        entry.level,
        None,
        0 if state.current_index == 0 else entry.log_idle_msecs,
        0,
        None,
        None,
        None,
        entry.log_filters,
    )
    return QueryResult(columns=columns, rows=[row])


def normalize_sql(sql: str) -> str:
    return " ".join(sql.lower().split())


def write_csv_output(state: State) -> str:
    rows, columns = rows_and_columns_for_export(state)
    output = io.StringIO()
    writer = csv.writer(output, lineterminator="\n")
    writer.writerow(columns)
    for row in rows:
        writer.writerow(["" if value is None else value for value in row])
    return output.getvalue()


def write_json_output(state: State) -> str:
    rows, columns = rows_and_columns_for_export(state)
    payload = [dict(zip(columns, row)) for row in rows]
    return json.dumps(payload, indent=4) + ("\n" if payload else "[]\n")


def write_jsonlines_output(state: State) -> str:
    rows, columns = rows_and_columns_for_export(state)
    lines = [json.dumps(dict(zip(columns, row))) for row in rows]
    return ("\n".join(lines) + "\n") if lines else ""


def rows_and_columns_for_export(state: State) -> tuple[list[tuple[object, ...]], list[str]]:
    if state.last_query is not None:
        return state.last_query.rows, state.last_query.columns
    columns = ["log_text"]
    rows = [(entry.raw_line,) for entry in state.visible_entries]
    return rows, columns


def format_table(result: QueryResult) -> str:
    if not result.columns:
        return ""

    formatted_rows = [tuple(format_value(value) for value in row) for row in result.rows]
    widths = [len(column) for column in result.columns]
    numeric = [all(isinstance(row[idx], (int, float)) and not isinstance(row[idx], bool) for row in result.rows) for idx in range(len(result.columns))]

    for row in formatted_rows:
        for idx, value in enumerate(row):
            widths[idx] = max(widths[idx], len(value))

    def format_cell(value: str, idx: int, *, header: bool = False) -> str:
        width = widths[idx]
        if header:
            return f" {value:<{width}} "
        if numeric[idx]:
            return f" {value:>{width}} "
        return f" {value:<{width}} "

    lines = []
    lines.append("".join(format_cell(column, idx, header=True) for idx, column in enumerate(result.columns)).rstrip() + " \n")
    for row in formatted_rows:
        lines.append("".join(format_cell(value, idx) for idx, value in enumerate(row)).rstrip() + " \n")
    return "".join(lines)


def format_value(value: object) -> str:
    if value is None:
        return "<NULL>"
    if isinstance(value, str):
        return value
    return str(value)


def render_log_lines(entries: Iterable[Entry]) -> str:
    lines = [entry.raw_line for entry in entries]
    return ("\n".join(lines) + "\n") if lines else ""


def render_plain_lines(lines: Iterable[PlainLine]) -> str:
    values = [line.raw_line for line in lines]
    return ("\n".join(values) + "\n") if values else ""


def parse_line(line: str) -> tuple[datetime, str] | None:
    match = ISO_LINE_RE.match(line)
    if match:
        stamp = parse_timestamp(match.group("stamp"))
        if stamp is not None:
            return stamp, match.group("body")

    match = SYSLOG_RE.match(line)
    if match:
        stamp = parse_syslog_timestamp(match.group("stamp"))
        if stamp is not None:
            return stamp, match.group("body")
    return None


def parse_timestamp(value: str) -> datetime | None:
    normalized = value
    if normalized.endswith("Z"):
        normalized = normalized[:-1] + "+00:00"
    if re.search(r"[+-]\d{4}$", normalized):
        normalized = normalized[:-5] + normalized[-5:-2] + ":" + normalized[-2:]

    for candidate in (
        normalized,
        normalized.replace("T", " "),
    ):
        try:
            parsed = datetime.fromisoformat(candidate)
            if parsed.tzinfo is not None:
                parsed = parsed.astimezone(timezone.utc).replace(tzinfo=None)
            return parsed
        except ValueError:
            continue
    return None


def parse_syslog_timestamp(value: str) -> datetime | None:
    year = datetime.now().year
    for fmt in ("%b %d %H:%M:%S", "%b  %d %H:%M:%S"):
        try:
            parsed = datetime.strptime(f"{year} {value}", f"%Y {fmt}")
            return parsed
        except ValueError:
            continue
    return None


def ensure_timestamp(line: str) -> str:
    if parse_line(line) is not None:
        return line
    now = datetime.now(timezone.utc).astimezone()
    return f"{now.strftime('%Y-%m-%dT%H:%M:%S.%f%z')} {line}"


def detect_level(body: str) -> str:
    lowered = body.lower()
    if "error" in lowered:
        return "error"
    if "warning" in lowered or "warn" in lowered:
        return "warning"
    if "info" in lowered:
        return "info"
    if "debug" in lowered:
        return "debug"
    return "unknown"


def matches_filter(line: str, pattern: str) -> bool:
    if not pattern:
        return True
    try:
        return re.search(pattern, line) is not None
    except re.error:
        return pattern in line


def format_sql_time(value: datetime) -> str:
    return value.strftime("%Y-%m-%d %H:%M:%S.%f")


def read_text_file(path: Path) -> str:
    suffix = path.suffix.lower()
    if suffix == ".gz":
        with gzip.open(path, "rt", encoding="utf-8", errors="replace") as fh:
            return fh.read()
    if suffix == ".bz2":
        with bz2.open(path, "rt", encoding="utf-8", errors="replace") as fh:
            return fh.read()
    if suffix in {".xz", ".lzma"}:
        with lzma.open(path, "rt", encoding="utf-8", errors="replace") as fh:
            return fh.read()
    return path.read_text(encoding="utf-8", errors="replace")


def load_internal_help() -> str:
    resource = Path(__file__).resolve().parent.parent / "resources" / "internal_help.txt"
    return resource.read_text(encoding="utf-8")


def handle_install(arg: str) -> int:
    if arg == "extra":
        sys.stdout.write(
            "Cloning into '/opt/uiuc-agent/home/.lnav/remote-config'...\n"
            "fatal: unable to access 'https://github.com/tstack/lnav-config.git/': Could not resolve host: github.com\n"
            "Unable to open remote-config.json: No such file or directory\n"
            "Cloning lnav remote config repo...\n"
        )
        return 0
    return 0


def print_parse_error(exc: ParseError) -> None:
    sys.stderr.write(f"  error: {exc.message}\n")
    sys.stderr.write(f" reason: {exc.reason}\n")


def print_runtime_error(exc: RuntimeCliError) -> None:
    if not exc.lines:
        return
    for line in exc.lines:
        sys.stderr.write(f"{line}\n")


def print_ui_error() -> None:
    sys.stderr.write(
        "  error: unable to display interactive text UI\n"
        " reason: stdout is not a TTY\n"
        " = help: pass the -n option to run lnav in headless mode or don't redirect stdout\n"
    )


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))

