def main(argv: Sequence[str]) -> int:
    try:
        options = parse_args(argv[1:])
        if options.print_help:
            sys.stdout.write(render_help(argv[0]))
            return 0
        if options.print_version:
            sys.stdout.write(f"{VERSION}\n")
            return 0
        if options.update_formats:
            sys.stdout.write(
                "No formats from git repositories found, use 'lnav -i extra' to install third-party formats\n"
            )
            return 0
        if options.install_target is not None:
            return handle_install(options.install_target)
        if options.management_mode:
            return handle_management(options.management_args)
        if options.debug_file:
            Path(options.debug_file).write_text("", encoding="utf-8")
        if not options.headless and not sys.stdout.isatty():
            raise CliError(
                1,
                [
