                    raise CliError(
                        109,
                        ["  error: invalid command-line arguments", f" reason: The following argument was not expected: {flag}"],
                    )
                j += 1
        else:
            if saw_management and not options.inputs and not options.commands and not options.shell_commands:
                options.management_args.append(arg)
            else:
                options.inputs.append(arg)
        i += 1

    if options.management_mode:
        extras = [arg for arg in args if arg.startswith("-") and arg != "-m"]
        if extras:
            raise CliError(
                109,
                ["  error: invalid command-line arguments", f" reason: The following argument was not expected: {extras[0]}"],
            )
    return options


def parse_cutoff(value: str, which: str) -> datetime:
    parsed = parse_timestamp(value)
    if parsed is None:
        raise CliError(1, [f"  error: invalid '{which}' time “{value}”", " reason: Unrecognized input"])
    return parsed


def handle_install(target: str) -> int:
